19.     {
20.         if (discountPercent < 0 || discountPercent > 100)
21.             throw new ArgumentOutOfRangeException(nameof(discountPercent));
22. 
23.         return price * (1 - discountPercent / 100);
24.     }
25. 
26.     public string FormatPrice(decimal price, string currencySymbol = "$")
27.     {
28.         return $"{currencySymbol}{price:F2}";
29.     }
30. }
