using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service = new();

    private static List<OrderItem> CreateSampleItems() =>
    [
        new OrderItem { ProductName = "Widget", Price = 10.00m, Quantity = 2 },
        new OrderItem { ProductName = "Gadget", Price = 25.50m, Quantity = 1 }
    ];

    [TestClass]
    public sealed class CreateOrder
    {
        private readonly OrderService _service = new();

        [TestMethod]
        public void ReturnsOrder_WithCorrectCustomerId()
        {
            var order = _service.CreateOrder("cust-1", CreateSampleItems());

            Assert.AreEqual("cust-1", order.CustomerId);
        }

        [TestMethod]
        public void ReturnsOrder_WithGeneratedId()
        {
            var order = _service.CreateOrder("cust-1", CreateSampleItems());

            Assert.IsFalse(string.IsNullOrWhiteSpace(order.Id));
        }

        [TestMethod]
        public void ReturnsOrder_WithCorrectTotal()
        {
            var items = new List<OrderItem>
            {
                new() { ProductName = "Widget", Price = 10.00m, Quantity = 2 },
                new() { ProductName = "Gadget", Price = 25.50m, Quantity = 1 }
            };

            var order = _service.CreateOrder("cust-1", items);

            // (10 * 2) + (25.50 * 1) = 45.50
            Assert.AreEqual(45.50m, order.Total);
        }

        [TestMethod]
        public void ReturnsOrder_WithAllItems()
        {
            var items = CreateSampleItems();

            var order = _service.CreateOrder("cust-1", items);

            Assert.AreEqual(2, order.Items.Count);
        }

        [TestMethod]
        public void ReturnsOrder_WithCreatedAtSetToUtcNow()
        {
            var before = DateTime.UtcNow;

            var order = _service.CreateOrder("cust-1", CreateSampleItems());

            var after = DateTime.UtcNow;
            Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
        }

        [TestMethod]
        public void ThrowsArgumentNullException_WhenCustomerIdIsNull()
        {
            Assert.ThrowsExactly<ArgumentNullException>(
                () => _service.CreateOrder(null!, CreateSampleItems()));
        }

        [TestMethod]
        public void ThrowsArgumentNullException_WhenItemsIsNull()
        {
            Assert.ThrowsExactly<ArgumentNullException>(
                () => _service.CreateOrder("cust-1", null!));
        }

        [TestMethod]
        public void ThrowsInvalidOperationException_WhenItemsListIsEmpty()
        {
            Assert.ThrowsExactly<InvalidOperationException>(
                () => _service.CreateOrder("cust-1", []));
        }

        [TestMethod]
        public void GeneratesUniqueIds_ForMultipleOrders()
        {
            var order1 = _service.CreateOrder("cust-1", CreateSampleItems());
            var order2 = _service.CreateOrder("cust-1", CreateSampleItems());

            Assert.AreNotEqual(order1.Id, order2.Id);
        }
    }

    [TestClass]
    public sealed class GetOrder
    {
